package com.cupk.aiacademy.common;

public enum RecordStatus {
    DRAFT(0),
    ACTIVE(1),
    DISABLED(2);

    private final int code;

    RecordStatus(int code) {
        this.code = code;
    }

    public int getCode() {
        return code;
    }

    public static RecordStatus fromCode(Integer code) {
        if (code == null) {
            return ACTIVE;
        }
        for (RecordStatus status : values()) {
            if (status.code == code) {
                return status;
            }
        }
        return ACTIVE;
    }
}
package com.cupk.aiacademy.common;

public enum PaperStatus {
    DRAFT(0),
    PUBLISHED(1),
    ARCHIVED(2);

    private final int code;

    PaperStatus(int code) {
        this.code = code;
    }

    public int getCode() {
        return code;
    }

    public static PaperStatus fromCode(Integer code) {
        if (code == null || code == 0) {
            return DRAFT;
        }
        if (code == 1) {
            return PUBLISHED;
        }
        return ARCHIVED;
    }
}
